if(empty($_SESSION['admin'])){
 if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['login'])){if(hash_equals($adminUser,(string)($_POST['user']??''))&&hash_equals($adminPass,(string)($_POST['pass']??''))){session_regenerate_id(true);$_SESSION['admin']=true;header('Location: gestor.php');exit;}$error='Usuário ou senha inválidos.';}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gestor — JADIEL CHECK</title><style>body{margin:0;min-height:100vh;display:grid;place-items:center;background:#050807;color:#fff;font-family:system-ui}.box{width:min(390px,88%);padding:30px;border:1px solid #5cffaa33;border-radius:24px;background:#0b1511e8;box-shadow:0 30px 100px #000}.brand{font-weight:900;font-size:22px;margin-bottom:22px}.brand span{color:#5cffaa}input,button{width:100%;height:52px;margin:7px 0;border-radius:13px;box-sizing:border-box}input{padding:0 14px;background:#ffffff08;border:1px solid #ffffff16;color:#fff}button{border:0;background:#5cffaa;font-weight:900}.err{color:#ff8585}</style></head><body><form class="box" method="post"><div class="brand">JADIEL <span>CHECK</span> · GESTOR</div><?php if(!empty($error)):?><p class="err"><?=htmlspecialchars($error)?></p><?php endif;?><input name="user" placeholder="Usuário" required><input name="pass" type="password" placeholder="Senha" required><button name="login">ENTRAR</button></form></body></html><?php exit; }
