if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['save_notice'])){$title=trim($_POST['title']??'');$message=trim($_POST['message']??'');$expires=trim($_POST['expires_at']??'');$notice=['active'=>true,'title'=>$title?:'Aviso','message'=>$message,'expires_at'=>$expires?:null,'updated_at'=>date('c')];file_put_contents($file,json_encode($notice,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE),LOCK_EX);header('Location: gestor.php?saved=1');exit;}
