></textarea><label>Expira em</label><input type="datetime-local" name="expires_at" value="<?=htmlspecialchars(!empty($notice['expires_at'])?date('Y-m-d\TH:i',strtotime($notice['expires_at'])):'')?>"><button class="save" name="save_notice">PUBLICAR AVISO</button></form><form method="post"><button class="delete" name="delete_notice">APAGAR AVISO</button></form></section></div></body></html>
